      case SOpArg(info, lifted, op) => SOpArg(info, lifted, oSub(op))
      case SIntArg(info, lifted, e) => SIntArg(info, lifted, nSub(e))
      case sarg => sarg
    }

    Some((resultTyp, resultArgs))
  }


